from collections import deque
seen=[[False]*22 for _ in range(26)]
regions=[]
for r in range(26):
    for c in range(22):
        if G[r][c]!=8 and not seen[r][c]:
            q=deque([(r,c)]); seen[r][c]=True; cells=[]
            while q:
                a,b=q.popleft(); cells.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<26 and 0<=nb<22 and not seen[na][nb] and G[na][nb]!=8:
                        seen[na][nb]=True; q.append((na,nb))
            rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
            regions.append((min(rs),max(rs),min(cs),max(cs)))
out=[row[:] for row in G]
for r0,r1,c0,c1 in regions:
    nz=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if G[r][c]!=0]
    assert len({G[r][c] for r,c in nz})==1
    color=G[nz[0][0]][nz[0][1]]
    pr0=min(r for r,_ in nz); pr1=max(r for r,_ in nz)
    pc0=min(c for _,c in nz); pc1=max(c for _,c in nz)
    P=[[G[r][c] for c in range(pc0,pc1+1)] for r in range(pr0,pr1+1)]
    ph,pw=len(P),len(P[0])
    print(color,P)
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            out[r][c]=P[(r-pr0)%ph][(c-pc0)%pw]
print('\n'.join(' '.join(map(str,row)) for row in out))
